class Solution {
public:
    vector<int> maxTargetNodes(vector<vector<int>>& edges1, vector<vector<int>>& edges2, int k) {
        int n = edges1.size() + 1;
        int m = edges2.size() + 1;

        auto buildAdj = [](const vector<vector<int>>& edges, int size) {
            vector<vector<int>> adj(size);
            for (const auto& e : edges) {
                adj[e[0]].push_back(e[1]);
                adj[e[1]].push_back(e[0]);
            }
            return adj;
        };

        auto adj1 = buildAdj(edges1, n);
        auto adj2 = buildAdj(edges2, m);

        auto countWithin = [](const vector<vector<int>>& adj, int start, int limit) {
            if (limit < 0) return 0;
            int size = adj.size();
            vector<bool> visited(size, false);
            queue<pair<int, int>> q;
            q.push({start, 0});
            visited[start] = true;
            int cnt = 0;
            while (!q.empty()) {
                auto [u, d] = q.front();
                q.pop();
                cnt++;
                if (d < limit) {
                    for (int v : adj[u]) {
                        if (!visited[v]) {
                            visited[v] = true;
                            q.push({v, d + 1});
                        }
                    }
                }
            }
            return cnt;
        };

        int maxT2 = 0;
        if (k > 0) {
            for (int j = 0; j < m; ++j) {
                maxT2 = max(maxT2, countWithin(adj2, j, k - 1));
            }
        }

        vector<int> ans(n);
        for (int i = 0; i < n; ++i) {
            ans[i] = countWithin(adj1, i, k) + maxT2;
        }
        return ans;
    }
};

class Solution {
    public int[] maxTargetNodes(int[][] edges1, int[][] edges2, int k) {
        int n = edges1.length + 1;
        int m = edges2.length + 1;

        List<Integer>[] adj1 = buildAdj(edges1, n);
        List<Integer>[] adj2 = buildAdj(edges2, m);

        int maxT2 = 0;
        if (k > 0) {
            for (int j = 0; j < m; ++j) {
                maxT2 = Math.max(maxT2, countWithin(adj2, j, k - 1));
            }
        }

        int[] ans = new int[n];
        for (int i = 0; i < n; ++i) {
            ans[i] = countWithin(adj1, i, k) + maxT2;
        }
        return ans;
    }

    private List<Integer>[] buildAdj(int[][] edges, int size) {
        List<Integer>[] adj = new ArrayList[size];
        for (int i = 0; i < size; ++i) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        return adj;
    }

    private int countWithin(List<Integer>[] adj, int start, int limit) {
        if (limit < 0) return 0;
        boolean[] visited = new boolean[adj.length];
        Queue<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{start, 0});
        visited[start] = true;
        int cnt = 0;
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int u = curr[0], d = curr[1];
            cnt++;
            if (d < limit) {
                for (int v : adj[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        q.offer(new int[]{v, d + 1});
                    }
                }
            }
        }
        return cnt;
    }
}

var maxTargetNodes = function(edges1, edges2, k) {
    const n = edges1.length + 1;
    const m = edges2.length + 1;

    const buildAdj = (edges, size) => {
        const adj = Array.from({ length: size }, () => []);
        for (const [u, v] of edges) {
            adj[u].push(v);
            adj[v].push(u);
        }
        return adj;
    };

    const adj1 = buildAdj(edges1, n);
    const adj2 = buildAdj(edges2, m);

    const countWithin = (adj, start, limit) => {
        if (limit < 0) return 0;
        const visited = new Uint8Array(adj.length);
        const q = [[start, 0]];
        visited[start] = 1;
        let cnt = 0;
        let head = 0;
        while (head < q.length) {
            const [u, d] = q[head++];
            cnt++;
            if (d < limit) {
                for (const v of adj[u]) {
                    if (!visited[v]) {
                        visited[v] = 1;
                        q.push([v, d + 1]);
                    }
                }
            }
        }
        return cnt;
    };

    let maxT2 = 0;
    if (k > 0) {
        for (let j = 0; j < m; j++) {
            maxT2 = Math.max(maxT2, countWithin(adj2, j, k - 1));
        }
    }

    const ans = new Array(n);
    for (let i = 0; i < n; i++) {
        ans[i] = countWithin(adj1, i, k) + maxT2;
    }
    return ans;
};
